import os
import hashlib
import base64
from flask import Flask, request, jsonify, session
from lxml import etree
import requests

app = Flask(__name__)
app.secret_key = os.environ.get('FLASK_SECRET', 'change-me-in-production')

DOCUMENT_STORE = '/var/lib/docstore/'

def validate_api_key(key):
    """Validate API key against stored hash."""
    stored_hash = os.environ.get('API_KEY_HASH', '')
    provided_hash = hashlib.sha256(key.encode()).hexdigest()
    # Timing-safe comparison
    return provided_hash == stored_hash

def parse_document(xml_content):
    """Parse XML document and extract metadata fields."""
    parser = etree.XMLParser(
        resolve_entities=True,
        dtd_validation=False,
        load_dtd=True,
        no_network=False
    )
    try:
        doc = etree.fromstring(xml_content.encode('utf-8'), parser=parser)
    except etree.XMLSyntaxError as e:
        return None, str(e)

    metadata = {}
    for field in doc.iter():
        if field.text and field.text.strip():
            metadata[field.tag] = field.text.strip()

    return metadata, None

def store_document(doc_id, metadata):
    """Store parsed document metadata."""
    filepath = os.path.join(DOCUMENT_STORE, f"{doc_id}.meta")
    with open(filepath, 'w') as f:
        for key, val in metadata.items():
            f.write(f"{key}={val}\n")
    return filepath

@app.route('/api/v2/documents/import', methods=['POST'])
def import_document():
    api_key = request.headers.get('X-API-Key', '')
    if not validate_api_key(api_key):
        return jsonify({'error': 'unauthorized'}), 401

    content_type = request.content_type or ''
    if 'xml' not in content_type.lower() and 'text' not in content_type.lower():
        return jsonify({'error': 'content-type must be xml or text'}), 415

    xml_body = request.get_data(as_text=True)
    if not xml_body:
        return jsonify({'error': 'empty body'}), 400

    # Size check
    if len(xml_body) > 10 * 1024 * 1024:  # 10MB
        return jsonify({'error': 'payload too large'}), 413

    metadata, err = parse_document(xml_body)
    if err:
        return jsonify({'error': f'parse failed: {err}'}), 422

    doc_id = hashlib.md5(xml_body.encode()).hexdigest()
    filepath = store_document(doc_id, metadata)

    return jsonify({
        'doc_id': doc_id,
        'fields_extracted': len(metadata),
        'stored_at': filepath
    }), 201

@app.route('/api/v2/documents/<doc_id>', methods=['GET'])
def get_document(doc_id):
    # Path traversal protection
    safe_id = os.path.basename(doc_id)
    filepath = os.path.join(DOCUMENT_STORE, f"{safe_id}.meta")
    if not os.path.exists(filepath):
        return jsonify({'error': 'not found'}), 404

    with open(filepath, 'r') as f:
        content = f.read()

    fields = {}
    for line in content.strip().split('\n'):
        if '=' in line:
            k, v = line.split('=', 1)
            fields[k] = v

    return jsonify({'doc_id': safe_id, 'metadata': fields}), 200

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.4.1'}), 200

if __name__ == '__main__':
    os.makedirs(DOCUMENT_STORE, exist_ok=True)
    app.run(host='0.0.0.0', port=8080, debug=False)
